python3 - <<'EOF'
p='src/run.test.ts'; s=open(p).read()
anchor='	it("answers a trigger, posts once, and pushes the thread to the remote", async () => {'
new='''	it("leaves the checkout's git hooks alone, so pi commits in the repository's own format", async () => {
		const w = world();
		const message = "release: v0.35.1";
		w.faux.setResponses([
			fauxAssistantMessage(
				[
					fauxToolCall("bash", {
						command: `git commit -q --allow-empty -m "${message}" && git log -1 --format=%B`,
					}),
				],
				{ stopReason: "toolUse" },
			),
			(context) =>
				fauxAssistantMessage(`Committed: ${toolText(context.messages)}`),
		]);
		const deps = w.deps(w.comment("@pi cut the release"));
		// A repository whose hooks live in the working tree (husky, lefthook, a committed .githooks/).
		git(deps.cwd, "config", "core.hooksPath", ".githooks");
		const hooksDirectory = join(deps.cwd, ".git", "hooks");
		const hooksBefore = readdirSync(hooksDirectory).toSorted();

		await run(deps);

		expect(readdirSync(hooksDirectory).toSorted()).toStrictEqual(hooksBefore);
		expect(hooksBefore.filter((name) => !name.endsWith(".sample"))).toStrictEqual(
			[],
		);
		expect(existsSync(join(deps.cwd, ".githooks"))).toBe(false);
		expect(git(deps.cwd, "status", "--porcelain")).toBe("");
		expect(git(deps.cwd, "log", "-1", "--format=%B").trim()).toBe(message);
		expect(w.gh.posted[0]).toContain(`Committed: ${message}`);
	});

'''
assert anchor in s
s=s.replace(anchor,new+anchor,1)
s=s.replace('import { mkdtempSync, readdirSync,','import {\n\texistsSync,\n\tmkdtempSync,\n\treaddirSync,',1)
open(p,'w').write(s)

p='src/entrypoints.test.ts'; s=open(p).read()
s=s.replace('import { execFileSync } from "node:child_process";\n','import { execFileSync } from "node:child_process";\nimport { existsSync, readFileSync } from "node:fs";\n')
s+='''
// The target repository owns its commit conventions: no step may write to its .git/hooks or core.hooksPath.
describe("action.yml", () => {
	const steps = readFileSync("action.yml", "utf8")
		.split("\\n")
		.filter((line) => line.trimStart().startsWith("run:"));
	const scripts = steps.flatMap((line) =>
		[...line.matchAll(/\\$\\{\\{ github\\.action_path \\}\\}\\/(\\S+)/gu)].flatMap(
			(match) => (match[1] ? [match[1]] : []),
		),
	);

	it("runs only scripts that exist", () => {
		expect(scripts).toStrictEqual(["src/index.ts", "src/push.ts"]);
		for (const script of scripts) {
			expect(existsSync(script)).toBe(true);
		}
	});

	it("installs no git hooks in the target repository", () => {
		expect(steps.length).toBeGreaterThan(0);
		for (const step of steps) {
			expect(step).not.toMatch(/hook/iu);
		}
	});
});
'''
open(p,'w').write(s)
EOF
grep -n "run:" action.yml
